 import React, { useState } from 'react'
import { supabase } from '../lib/supabase'
import VerifiedBadge from './VerifiedBadge'
import { User, Reply, Send, Trash2, MoreHorizontal, Flag, UserMinus, X } from 'lucide-react'
import { useToast } from '../contexts/ToastContext'

export default function CommentSection({ postId, comments, onRefresh, currentUser, postAuthorId }) {
    const { showToast } = useToast()
    const [newComment, setNewComment] = useState('')
    const [replyingTo, setReplyingTo] = useState(null)
    const [replyText, setReplyText] = useState('')
    const [submitting, setSubmitting] = useState(false)
    const [openMenuId, setOpenMenuId] = useState(null)
    const [showReportModal, setShowReportModal] = useState(null)
    const [reportReason, setReportReason] = useState('')
    const [reportDescription, setReportDescription] = useState('')
    const [reporting, setReporting] = useState(false)
    const [showBlockConfirm, setShowBlockConfirm] = useState(null)

    const isAdmin = currentUser?.role === 'admin'

    const handleComment = async (e) => {
        e.preventDefault()
        if (!newComment.trim() || !currentUser) return

        setSubmitting(true)
        try {
            const { data, error } = await supabase
                .from('post_comments')
                .insert({
                    post_id: postId,
                    user_id: currentUser.id,
                    text: newComment.trim()
                })
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url, is_verified)
                `)
                .single()

            if (error) throw error

            await supabase
                .from('posts')
                .update({ comments_count: (comments?.length || 0) + 1 })
                .eq('id', postId)

            setNewComment('')
            if (onRefresh) onRefresh()
            showToast('Comment added!', 'success')
        } catch (error) {
            console.error('Error commenting:', error)
            showToast('Failed to add comment', 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const handleReply = async (commentId) => {
        if (!replyText.trim() || !currentUser) return

        setSubmitting(true)
        try {
            const { data, error } = await supabase
                .from('comment_replies')
                .insert({
                    comment_id: commentId,
                    user_id: currentUser.id,
                    text: replyText.trim()
                })
                .select()
                .single()

            if (error) throw error

            setReplyText('')
            setReplyingTo(null)
            if (onRefresh) onRefresh()
            showToast('Reply added!', 'success')
        } catch (error) {
            console.error('Error replying:', error)
            showToast('Failed to add reply', 'error')
        } finally {
            setSubmitting(false)
        }
    }

    const handleDeleteComment = async (commentId) => {
        try {
            await supabase
                .from('comment_replies')
                .delete()
                .eq('comment_id', commentId)

            await supabase
                .from('post_comments')
                .delete()
                .eq('id', commentId)

            await supabase
                .from('posts')
                .update({ comments_count: Math.max(0, (comments?.length || 0) - 1) })
                .eq('id', postId)

            setOpenMenuId(null)
            if (onRefresh) onRefresh()
            showToast('Comment deleted', 'info')
        } catch (error) {
            console.error('Error deleting comment:', error)
            showToast('Failed to delete comment', 'error')
        }
    }

    const handleDeleteReply = async (replyId) => {
        try {
            await supabase
                .from('comment_replies')
                .delete()
                .eq('id', replyId)

            setOpenMenuId(null)
            if (onRefresh) onRefresh()
            showToast('Reply deleted', 'info')
        } catch (error) {
            console.error('Error deleting reply:', error)
            showToast('Failed to delete reply', 'error')
        }
    }

    const handleReport = async () => {
        if (!reportReason.trim()) {
            showToast('Please select a reason', 'warning')
            return
        }

        setReporting(true)
        try {
            const reportData = {
                reporter_id: currentUser.id,
                reason: reportReason,
                description: reportDescription.trim() || null,
                status: 'pending'
            }

            if (showReportModal.type === 'comment') {
                reportData.comment_id = showReportModal.id
            } else {
                reportData.reply_id = showReportModal.id
            }

            const { error } = await supabase
                .from('comment_reports')
                .insert(reportData)

            if (error) throw error

            showToast('Report submitted. Moderators will review it.', 'success')
            setShowReportModal(null)
            setReportReason('')
            setReportDescription('')
            setOpenMenuId(null)
        } catch (error) {
            console.error('Error reporting:', error)
            showToast('Failed to submit report', 'error')
        } finally {
            setReporting(false)
        }
    }

    const handleBlockUser = async () => {
        try {
            const { error } = await supabase
                .from('blocks')
                .insert({
                    blocker_id: currentUser.id,
                    blocked_id: showBlockConfirm.userId
                })

            if (error) throw error

            showToast(`You have blocked ${showBlockConfirm.username}`, 'info')
            setShowBlockConfirm(null)
            setOpenMenuId(null)
        } catch (error) {
            console.error('Error blocking user:', error)
            showToast('Failed to block user', 'error')
        }
    }

    const canDeleteComment = (comment) => {
        if (!currentUser) return false
        if (isAdmin) return true
        if (comment.user_id === currentUser.id) return true
        if (postAuthorId === currentUser.id) return true
        return false
    }

    const canDeleteReply = (reply) => {
        if (!currentUser) return false
        if (isAdmin) return true
        if (reply.user_id === currentUser.id) return true
        if (postAuthorId === currentUser.id) return true
        return false
    }

    const canBlockUser = (userId) => {
        if (!currentUser) return false
        if (userId === currentUser.id) return false
        if (isAdmin) return false
        return true
    }

    const canReport = () => {
        return !!currentUser
    }

    const toggleMenu = (id) => {
        setOpenMenuId(prev => prev === id ? null : id)
    }

    return (
        <div>
            {comments?.map((comment) => {
                const isCommentAuthor = comment.user_id === currentUser?.id
                const menuId = `comment-${comment.id}`

                return (
                    <div key={comment.id} className="mb-3">
                        <div className="flex gap-2">
                            <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center text-xs font-bold">
                                <User size={14} />
                            </div>
                            <div className="flex-1">
                                <div className="bg-gray-100 rounded-lg px-3 py-2">
                                    <div className="font-semibold flex items-center gap-1.5 text-sm">
                                        {comment.profiles?.full_name || comment.profiles?.username || 'Unknown'}
                                        {comment.profiles?.is_verified && <VerifiedBadge size="sm" />}
                                    </div>
                                    <p className="text-sm text-gray-800">{comment.text}</p>
                                </div>
                                <div className="flex gap-4 mt-1 text-xs text-gray-500">
                                    <button 
                                        onClick={() => setReplyingTo(replyingTo === comment.id ? null : comment.id)}
                                        className="hover:text-green-600 transition flex items-center gap-1"
                                    >
                                        <Reply size={12} /> Reply
                                    </button>
                                    <span>{new Date(comment.created_at).toLocaleDateString()}</span>
                                </div>

                                {comment.replies?.map((reply) => (
                                    <div key={reply.id} className="flex gap-2 mt-2 ml-8">
                                        <div className="w-6 h-6 bg-gray-300 rounded-full flex items-center justify-center text-[10px] font-bold">
                                            <User size={12} />
                                        </div>
                                        <div className="flex-1">
                                            <div className="bg-gray-50 rounded-lg px-3 py-1.5">
                                                <div className="font-semibold flex items-center gap-1.5 text-xs">
                                                    {reply.profiles?.full_name || reply.profiles?.username || 'Unknown'}
                                                    {reply.profiles?.is_verified && <VerifiedBadge size="sm" />}
                                                </div>
                                                <p className="text-sm text-gray-700">{reply.text}</p>
                                            </div>
                                        </div>
                                    </div>
                                ))}

                                {replyingTo === comment.id && (
                                    <div className="flex gap-2 mt-2 ml-8">
                                        <input
                                            type="text"
                                            value={replyText}
                                            onChange={(e) => setReplyText(e.target.value)}
                                            placeholder="Write a reply..."
                                            className="flex-1 px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                                        />
                                        <button
                                            onClick={() => handleReply(comment.id)}
                                            disabled={submitting || !replyText.trim()}
                                            className="px-3 py-1.5 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700 disabled:opacity-50 flex items-center gap-1"
                                        >
                                            <Send size={14} /> Reply
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                )
            })}

            <form onSubmit={handleComment} className="flex gap-2 mt-2">
                <input
                    type="text"
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    placeholder="Write a comment..."
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                />
                <button
                    type="submit"
                    disabled={submitting || !newComment.trim()}
                    className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-semibold hover:bg-green-700 disabled:opacity-50 flex items-center gap-1"
                >
                    <Send size={16} /> Post
                </button>
            </form>

            {/* Report Modal */}
            {showReportModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-gray-800">Report {showReportModal.type === 'comment' ? 'Comment' : 'Reply'}</h3>
                            <button onClick={() => setShowReportModal(null)} className="text-gray-400 hover:text-gray-600">
                                <X size={24} />
                            </button>
                        </div>

                        <div className="mb-4">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Reason *</label>
                            <select
                                value={reportReason}
                                onChange={(e) => setReportReason(e.target.value)}
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                            >
                                <option value="">Select a reason</option>
                                <option value="Harassment">Harassment</option>
                                <option value="Hate speech">Hate speech</option>
                                <option value="Spam">Spam</option>
                                <option value="Offensive content">Offensive content</option>
                                <option value="Impersonation">Impersonation</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>

                        <div className="mb-4">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Additional details (optional)</label>
                            <textarea
                                value={reportDescription}
                                onChange={(e) => setReportDescription(e.target.value)}
                                placeholder="Provide more context..."
                                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
                                rows="3"
                            />
                        </div>

                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowReportModal(null)}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleReport}
                                disabled={reporting || !reportReason.trim()}
                                className="flex-1 bg-orange-600 text-white py-2 rounded-lg hover:bg-orange-700 transition disabled:opacity-50"
                            >
                                {reporting ? 'Submitting...' : 'Submit Report'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Block Modal */}
            {showBlockConfirm && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6">
                        <div className="text-center mb-4">
                            <div className="text-4xl mb-2">🚫</div>
                            <h3 className="text-xl font-bold text-gray-800">Block {showBlockConfirm.username}?</h3>
                            <p className="text-gray-500 mt-1">
                                They won't be able to comment on your posts or send you messages. You can unblock them later.
                            </p>
                        </div>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowBlockConfirm(null)}
                                className="flex-1 bg-gray-200 text-gray-700 py-2 rounded-lg hover:bg-gray-300 transition"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleBlockUser}
                                className="flex-1 bg-red-600 text-white py-2 rounded-lg hover:bg-red-700 transition"
                            >
                                Block User
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}
